# Formatting: all figures/tables fit one JOIV column (86.45 mm).
def setup(doc,columns=False):
 for sec in doc.sections:
  sec.page_width=Mm(210);sec.page_height=Mm(297);sec.top_margin=Mm(19);sec.bottom_margin=Mm(28);sec.left_margin=sec.right_margin=Mm(14.32)
  for p in sec.header.paragraphs+sec.footer.paragraphs:p.text=''
 style=doc.styles['Normal'];style.font.name='Times New Roman';style.font.size=Pt(10);style.paragraph_format.space_after=Pt(3);style.paragraph_format.line_spacing=1;style.paragraph_format.first_line_indent=Mm(3)
 for h in ['Heading 1','Heading 2','Heading 3']:
  doc.styles[h].font.name='Times New Roman';doc.styles[h].font.size=Pt(10);doc.styles[h].font.color.rgb=None
  doc.styles[h].paragraph_format.keep_with_next=True
 doc.styles['Heading 1'].font.bold=False;doc.styles['Heading 1'].font.small_caps=True;doc.styles['Heading 1'].paragraph_format.alignment=WD_ALIGN_PARAGRAPH.CENTER
 doc.styles['Heading 2'].font.bold=False;doc.styles['Heading 2'].font.italic=True
 if columns:setcols(doc.sections[-1],2)
def setcols(sec,n):
 c=sec._sectPr.find(qn('w:cols'))
 if c is None:c=OxmlElement('w:cols');sec._sectPr.append(c)
 c.set(qn('w:num'),str(n));c.set(qn('w:space'),'482');c.set(qn('w:equalWidth'),'1')
def p(doc,text,style=None):
 z=doc.add_paragraph(text,style);z.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
 if style:z.paragraph_format.first_line_indent=Mm(0)
 return z
def head(doc,text):return p(doc,text,'Heading 1')
def sub(doc,text):return p(doc,text,'Heading 2')
def table(doc,roman,title,headers,rows,widths=None):
 cap=doc.add_paragraph('TABLE '+roman+'\n'+title.upper());cap.alignment=WD_ALIGN_PARAGRAPH.CENTER;cap.paragraph_format.first_line_indent=Mm(0);cap.paragraph_format.keep_with_next=True
 for run in cap.runs:run.font.size=Pt(8)
 t=doc.add_table(rows=1,cols=len(headers));t.autofit=False;t.alignment=1
 if widths is None:widths=[86.3/len(headers)]*len(headers)
 for i,w in enumerate(widths):t.columns[i].width=Mm(w)
 tw=t._tbl.tblPr.find(qn('w:tblW'));tw.set(qn('w:type'),'dxa');tw.set(qn('w:w'),str(int(Mm(sum(widths)).twips)))
 # A fixed grid width is essential in a two-column section.
 for col,w in zip(t._tbl.tblGrid.gridCol_lst,widths):col.set(qn('w:w'),str(int(Mm(w).twips)))

 for i,h in enumerate(headers):t.rows[0].cells[i].text=str(h)
 for row in rows:
  cells=t.add_row().cells
  for i,v in enumerate(row):cells[i].text=str(v)
 for row in t.rows:
  pr=row._tr.get_or_add_trPr();pr.append(OxmlElement('w:cantSplit'))
  for i,c in enumerate(row.cells):
   c.width=Mm(widths[i]);c.vertical_alignment=1
   for par in c.paragraphs:
    par.paragraph_format.first_line_indent=Mm(0);par.paragraph_format.space_after=Pt(2);par.paragraph_format.space_before=Pt(1);par.paragraph_format.line_spacing=1
    for run in par.runs:run.font.name='Times New Roman';run.font.size=Pt(8)
 # Keep short tables together instead of splitting across pages or columns.
 for row in t.rows[:-1]:
  for c in row.cells:
   for par in c.paragraphs:par.paragraph_format.keep_with_next=True
 # Repeat table headings and use simple horizontal rules.
 pr=t.rows[0]._tr.get_or_add_trPr();pr.append(OxmlElement('w:tblHeader'))
 for c in t.rows[0].cells:
  for run in c.paragraphs[0].runs:run.bold=True
 borders=OxmlElement('w:tblBorders')
 for k in ['top','bottom','insideH']:
  a=OxmlElement('w:'+k);a.set(qn('w:val'),'single');a.set(qn('w:sz'),'4');a.set(qn('w:color'),'888888');borders.append(a)
 t._tbl.tblPr.append(borders)
 doc.add_paragraph().paragraph_format.space_after=Pt(0)
 return t
