def crossref(doi,year=None):
 a=cr[doi];authors=a['author'];name=lambda x:''.join(v[0]+'. ' for v in x.get('given','').split())+x['family'];au=', '.join(name(x) for x in authors[:3])+(' et al.' if len(authors)>3 else '')
 yy=year or a.get('published-print',a['published'])['date-parts'][0][0] if a.get('published-print') else year or a['published']['date-parts'][0][0]
 loc='vol. '+str(a['volume']) if a.get('volume') else '';page=a.get('page') or a.get('article-number');loc+=(', '+('Art. no. ' if page and '-' not in str(page) else 'pp. ')+str(page)) if page else ''
 return f'{au}, “{a["title"][0]},” {a["container-title"][0]}, {loc}, {yy}, doi: {doi}.'
